-- Canonical academic data is authoritative; IDs are never matched by numeric equality.
CREATE TABLE academic_legacy_ids(entity TEXT NOT NULL,canonical_id INTEGER NOT NULL,legacy_id INTEGER NOT NULL,PRIMARY KEY(entity,canonical_id),UNIQUE(entity,legacy_id));
CREATE TABLE academic_projection_state(id INTEGER PRIMARY KEY CHECK(id=1),revision INTEGER NOT NULL DEFAULT 1,applied_revision INTEGER NOT NULL DEFAULT -1);
INSERT INTO academic_projection_state(id) VALUES(1);
ALTER TABLE classroom_feed_v2 ADD COLUMN description TEXT;
ALTER TABLE classroom_feed_v2 ADD COLUMN due_at INTEGER;
ALTER TABLE classroom_feed_v2 ADD COLUMN materials_json TEXT NOT NULL DEFAULT '[]';
ALTER TABLE classroom_feed_v2 ADD COLUMN submission_state TEXT;
ALTER TABLE classroom_feed_v2 ADD COLUMN source_state TEXT;
CREATE TABLE legacy_classroom_activity_links(user_id INTEGER NOT NULL REFERENCES users(id),offering_id INTEGER NOT NULL REFERENCES offerings(id),external_id TEXT NOT NULL,legacy_activity_id INTEGER NOT NULL UNIQUE,PRIMARY KEY(user_id,offering_id,external_id));
CREATE TABLE institution_timezones(institution_id INTEGER PRIMARY KEY REFERENCES institutions(id),time_zone TEXT NOT NULL DEFAULT 'America/Bahia');
CREATE TRIGGER projection_institutions_insert AFTER INSERT ON institutions BEGIN UPDATE academic_projection_state SET revision=revision+1 WHERE id=1; END;
